import json, html

questions = json.load(open('questions.json', encoding='utf-8'))
STEP_NAMES = ["Первый", "Второй", "Третий", "Четвертый", "Пятый", "Шестой", "Седьмой", "Восьмой"]

def esc(s):
    return html.escape(s, quote=False)

# Cards, three questions per step
question_no = 1
step_panes = []
for step in range(8):
    cards = []
    for q in range(3):
        items = questions[step * 3 + q]
        qn = question_no
        question_no += 1
        opts = []
        for pos, item in enumerate(items):
            opts.append(
                f'''<li class="option" data-type="{item['type']}" data-pos="{pos}" data-orig="{pos}" tabindex="0" aria-posinset="{pos + 1}" aria-setsize="4">\n'''
                f'''  <span class="option-rank" aria-hidden="true">{pos + 1}</span>\n'''
                f'''  <span class="option-text">{esc(item['text'])}</span>\n'''
                f'''  <span class="option-handle" aria-hidden="true"><svg viewBox="0 0 14 20" fill="currentColor" focusable="false"><circle cx="4" cy="4" r="1.5"/><circle cx="10" cy="4" r="1.5"/><circle cx="4" cy="10" r="1.5"/><circle cx="10" cy="10" r="1.5"/><circle cx="4" cy="16" r="1.5"/><circle cx="10" cy="16" r="1.5"/></svg></span>\n'''
                f'''</li>'''
            )
        cards.append(
            f'''<article class="q-card" aria-labelledby="q-title-{qn}">\n'''
            f'''  <div class="q-head">\n'''
            f'''    <span class="q-index" id="q-title-{qn}">Вопрос {qn:02d}</span>\n'''
            f'''    <span class="q-range"><svg viewBox="0 0 14 14" fill="none" aria-hidden="true" focusable="false"><path d="M7 11.3V2.7M3.3 6.4 7 2.7l3.7 3.7" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>Я наиболее</span>\n'''
            f'''  </div>\n'''
            f'''  <ul class="rank-list" data-question="{qn}" aria-label="Вопрос {qn}: расположите варианты от наиболее похожего на вас до наименее похожего" aria-describedby="rankHelp">\n'''
            + '\n'.join(opts) +
            f'''\n  </ul>\n'''
            f'''  <div class="q-foot"><svg viewBox="0 0 14 14" fill="none" aria-hidden="true" focusable="false"><path d="M7 2.7v8.6M3.3 7.6 7 11.3l3.7-3.7" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>Я наименее</div>\n'''
            f'''</article>'''
        )
    panes = f'''<div class="step-pane{' is-active' if step == 0 else ''}" id="step-pane-{step}" role="tabpanel" aria-labelledby="step-tab-{step}" data-step-pane="{step}"{' hidden' if step else ''}>\n<div class="questions-grid">\n''' + '\n'.join(cards) + '\n</div>\n</div>'
    step_panes.append(panes)

tabs = []
for i, name in enumerate(STEP_NAMES):
    tabs.append(
        f'''<button class="step-tab{' is-active' if i == 0 else ''}" id="step-tab-{i}" type="button" role="tab" aria-selected="{'true' if i == 0 else 'false'}" aria-controls="step-pane-{i}" data-step="{i}" tabindex="{'0' if i == 0 else '-1'}"><span class="step-num" aria-hidden="true">{i + 1:02d}</span><span>{name}</span></button>'''
    )

